#include "clocked_uart.hpp"
#include <iostream>
#include <vector>
using iris_board::ClockedUart;
static void check(bool c,const char*m){if(!c)throw std::runtime_error(m);}
static void write(ClockedUart&u,uint64_t a,uint32_t v,unsigned n=4){uint8_t b[4];for(unsigned i=0;i<n;++i)b[i]=v>>(8*i);check(u.store(a,n,b),"store");}
static uint32_t read(ClockedUart&u,uint64_t a,unsigned n=4){uint8_t b[4]{};check(u.load(a,n,b),"load");uint32_t v=0;for(unsigned i=0;i<n;++i)v|=uint32_t(b[i])<<(8*i);return v;}
static ClockedUart uart(){return {{256,256,135,8},{500000000,500000}};}
template<class F>static void rejected(F action){bool caught=false;try{action();}catch(const std::exception&){caught=true;}check(caught,"invalid/unknown silently accepted");}
int main(){unsigned cases=0;try{
  {auto u=uart();std::vector<uint8_t> bytes;u.registers().on_transmitted([&](uint8_t b){bytes.push_back(b);});write(u,0,'A');u.iris_advance_model_clock(0,500,100000000);check(u.uart_cycles()==2500&&u.registers().tx_count()==1&&bytes.empty(),"disabled source clock");check(!u.iris_next_model_event(500,100000000),"disabled deadline");write(u,8,1);u.iris_advance_model_clock(500,501,100000000);check(u.registers().tx_busy()&&u.registers().tx_count()==0,"clock did not dequeue");auto edge=u.iris_next_model_event(501,100000000);check(edge&&*edge==746,"frame deadline");u.iris_advance_model_clock(501,745,100000000);check(bytes.empty(),"early serial completion");u.iris_advance_model_clock(745,746,100000000);check(bytes==std::vector<uint8_t>{'A'},"missing completion");auto n=u.uart_cycles();u.tick(1000);check(u.uart_cycles()==n,"RTC double counted live time");++cases;}
  {auto a=uart(),b=uart();write(a,8,1);write(b,8,1);write(a,0,42);write(b,0,42);a.iris_advance_model_clock(0,1000,100000000);b.iris_advance_model_clock(0,10000,1000000000);check(a.uart_cycles()==5000&&b.uart_cycles()==5000&&a.registers().tx_busy()==b.registers().tx_busy(),"base frequencies changed physical UART speed");++cases;}
  {auto u=uart();for(unsigned i=0;i<1000;++i)u.iris_advance_model_clock(i,i+1,333000000);check(u.uart_cycles()==1501,"fractional domain drift");rejected([&]{u.iris_advance_model_clock(1000,1001,100000000);});rejected([&]{u.iris_advance_model_clock(999,1001,333000000);});++cases;}
  {auto u=uart();u.tick(3);check(u.uart_cycles()==3000,"functional RTC domain ratio");rejected([&]{u.iris_advance_model_clock(0,1,100000000);});++cases;}
  {auto u=uart();std::vector<bool> irq;u.registers().on_interrupt([&](bool b){irq.push_back(b);});write(u,8,0x1000001);write(u,0x10,1);for(unsigned i=0;i<256;++i)write(u,0,i);check(read(u,0)==0x80000000&&!u.registers().irq(),"finite FIFO/full watermark");write(u,0,99);u.iris_advance_model_clock(0,1,500000000);check(u.registers().tx_count()==255&&u.registers().irq(),"UART pop deadline IRQ");check(irq==std::vector<bool>({false,true,false,true}),"IRQ transitions");++cases;}
  {auto u=uart();write(u,8,1);write(u,0,3);write(u,0,4);u.iris_advance_model_clock(0,2,500000000);write(u,8,0);auto edge=u.iris_next_model_event(2,500000000);check(edge.has_value(),"disabled active frame lost deadline");u.iris_advance_model_clock(2,*edge,500000000);check(!u.registers().tx_busy()&&u.registers().tx_count()==1&&!u.iris_next_model_event(*edge,500000000),"txen canceled frame or drained disabled queue");++cases;}
  {auto u=uart();check(read(u,7,1)==0x80,"empty status byte");rejected([&]{read(u,4);});write(u,0xc,1);write(u,0xe,255,2);write(u,0x10,2);for(unsigned i=0;i<256;++i)check(u.registers().begin_rx_frame()&&u.registers().complete_rx_frame(i),"RX depth");check(u.registers().irq(),"RX9bit threshold");check(u.registers().begin_rx_frame()&&!u.registers().complete_rx_frame(99),"RX overflow");for(unsigned i=0;i<256;++i)check(read(u,4)==i,"RX order");check(read(u,4)==0x80000000,"known stale data after wrap");++cases;}
  {auto u=uart();u.schedule_rx_frame(10,20,99);u.schedule_rx_frame(30,40,42);rejected([&]{u.schedule_rx_frame(35,50,1);});u.iris_advance_model_clock(0,10,500000000);write(u,0xc,1);u.iris_advance_model_clock(10,20,500000000);check(u.registers().rx_count()==0,"disabled frame accepted");u.iris_advance_model_clock(20,30,500000000);write(u,0xc,0);write(u,0x10,2);auto edge=u.iris_next_model_event(30,500000000);check(edge&&*edge==40,"RX deadline");u.iris_advance_model_clock(30,40,500000000);check(u.registers().irq()&&read(u,4)==42&&!u.registers().irq(),"in-flight RX completion/IRQ after RX disable");++cases;}
  {auto u=uart();write(u,0x18,65535);write(u,8,3);write(u,0,21);u.iris_advance_model_clock(0,3,500000000);write(u,0x18,0);write(u,8,1);u.iris_advance_model_clock(3,20,500000000);check(u.registers().tx_busy(),"old residual prescaler must survive DIV shrink");uint64_t guard=65536+11*(uint64_t(u.registers().divisor())+1);u.iris_advance_model_clock(20,20+guard,500000000);check(!u.registers().tx_busy()&&u.registers().tx_output(),"universal full-stop drain guard failed");++cases;}
  std::cout<<"uart_clock_cases="<<cases<<" source500MHz explicitRTC fractional deadlines FIFO IRQ unknownRX drain_bound pass\n";return 0;
}catch(const std::exception&e){std::cerr<<e.what()<<"\n";return 1;}}
